# tests/test_survey_pepper.py
import os
import hashlib
from ..config import SURVEY_PEPPER

def test_pepper_integration():
    sample_data = "survey_response_123"
    
    # Simulate hash with pepper
    hashed = hashlib.pbkdf2_hmac('sha256', 
                                sample_data.encode('utf-8'), 
                                SURVEY_PEPPER.encode('utf-8'), 
                                100000)
    
    # Verify deterministic output
    assert len(hashed) == 32  # 256-bit output
    
    # Test same input produces same hash
    assert hashed == hashlib.pbkdf2_hmac('sha256', 
                                       sample_data.encode('utf-8'), 
                                       SURVEY_PEPPER.encode('utf-8'), 
                                       100000)

def test_pepper_required():
    with pytest.raises(ValueError):
        # Test missing pepper raises error
        os.environ.pop('SURVEY_PEPPER')
        from ..config import SURVEY_PEPPER